// Formulate Trade Metadata under Rule 45 Google Shield
const filename = $input.item.json.filename || 'trade-installation.webp';
const cleanTitle = filename.replace('.webp', '').split('-').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');

let shieldAnchor = 'https://tvandhomesecurity.blogspot.com/';
if (filename.includes('starlink')) {
  shieldAnchor = 'https://adicommunications.co.uk/news/starlink-chimney-mount-vs-roof-apex/';
} else if (filename.includes('ajax')) {
  shieldAnchor = 'https://adicommunications.co.uk/news/ajax-wireless-alarm-grade-2-installation/';
} else if (filename.includes('cat6') || filename.includes('ethernet')) {
  shieldAnchor = 'https://adicommunications.co.uk/news/how-to-get-ethernet-upstairs-without-running-cables/';
} else if (filename.includes('tv') || filename.includes('fireplace')) {
  shieldAnchor = 'https://adicommunications.co.uk/news/tv-above-fireplace-safe-installation/';
}

const tradeDescription = `${cleanTitle} — Professional UK installation by Gary Pearce, ADI Communications (07860 244 274). 25+ years hands-on field craftsmanship, £10,000,000 Public Liability insurance, CAI-benchmarked hardware. Full Technical Debrief: ${shieldAnchor}`;

return {
  filename,
  cleanTitle,
  shieldAnchor,
  tradeDescription,
  apiKey: '6d207e02198a847aa98d0a2a901485a5'
};

// Extract the 3 Output Types (Type A, Type B, Type C)
const res = $input.item.json;
const img = res.image || {};

return {
  success: res.status_code === 200,
  filename: $('Rule 45 Metadata Formatter').item.json.filename,
  type_a_direct_url: img.url,
  type_a_thumb_url: img.thumb ? img.thumb.url : null,
  type_b_viewer_page: img.url_viewer,
  type_c_shield_anchor: $('Rule 45 Metadata Formatter').item.json.shieldAnchor,
  engineer: 'Gary Pearce',
  telephone: '07860 244 274',
  timestamp: new Date().toISOString()
};

